import{n as e}from"./rolldown-runtime-C0FnF6B9.js";var t;function n(){return(n=e((()=>{t='<!-- ui-kit-doc {\n  "schema": 1,\n  "name": "Selector",\n  "folder": "components/selector",\n  "kind": "component",\n  "category": "Overlays",\n  "status": "public",\n  "summary": "Panel for picking one or many things out of a list too long to render at once.",\n  "import": { "subpath": "components/selector", "barrel": true, "default": false },\n  "exports": ["Selector", "SelectorProps", "TSelectorItem", "SelectorAccessRightsMode", "RowLoader", "SearchLoader", "BreadCrumbsLoader"],\n  "providers": ["ThemeProvider", "TranslationProvider"],\n  "state": { "visibility": null, "close": "onClose", "loading": "isLoading", "disabled": null },\n  "related": ["aside", "search-input", "table"],\n  "subComponents": [],\n  "testIds": ["selector", "selector_search_input", "selector_submit_button", "selector_cancel_button"],\n  "storiesAudit": "2026-09-28"\n} -->\n\n# Selector\n\nPanel for picking one or many things out of a list too long to render at once. It is the\nportal\'s people picker, room picker and "save as" browser, and it brings its own search,\nbreadcrumbs, pagination and footer.\n\n## Use this when / not when\n\n- Use to choose users, groups, rooms, folders or files from a list you fetch a page at a time —\n  it virtualises the rows, asks for the next page as they scroll past, and gives you the\n  selection back in one callback.\n- Not for a short, fixed list of options — [`ComboBox`](../combobox/README.md) is that, and it\n  costs none of the pagination machinery.\n- Not for a table of data with columns — [`Table`](../table/README.md) is that.\n- Not as a dialog on its own. Selector has no visibility prop; it fills whatever box you put it\n  in. `useAside` is the one switch that turns it into a panel, and for anything else wrap it in\n  [`ModalDialog`](../modal-dialog/README.md) yourself.\n\n## Import\n\n```ts\nimport { Selector } from "@onlyoffice/apps-ui-kit/components/selector";\n```\n\nAlso exported from the root barrel `@onlyoffice/apps-ui-kit`.\n\nThe folder also exports the three skeletons its own props ask for — `RowLoader`,\n`SearchLoader`, `BreadCrumbsLoader` — and every type on this page.\n\nNeeds `ThemeProvider` from `@onlyoffice/apps-ui-kit/providers/theme`, and `TranslationProvider`\nfrom `@onlyoffice/apps-ui-kit/providers/translation` for the strings Selector prints on its own:\nthe user-type labels beside each person, and the empty screen\'s "Back" and "Clear filter" links.\n\n## Minimal example\n\nThe six empty-screen fields and the pagination four are required even for a list that never\npaginates, so the smallest working Selector is still a dozen props.\n\n```tsx\nimport { useCallback, useState } from "react";\nimport {\n  RowLoader,\n  Selector,\n  type TSelectorItem,\n} from "@onlyoffice/apps-ui-kit/components/selector";\n\nexport function PickOnePerson({ people }: { people: TSelectorItem[] }) {\n  const [chosen, setChosen] = useState<TSelectorItem | null>(null);\n\n  const loadNextPage = useCallback(async () => {}, []);\n\n  return (\n    <div style={{ width: 480, height: 485 }}>\n      <Selector\n        items={people}\n        totalItems={people.length}\n        hasNextPage={false}\n        isNextPageLoading={false}\n        isLoading={false}\n        disableFirstFetch\n        loadNextPage={loadNextPage}\n        rowLoader={<RowLoader isContainer />}\n        isMultiSelect={false}\n        selectedItem={chosen}\n        onSelect={(item) => setChosen(item)}\n        submitButtonLabel="Add"\n        disableSubmitButton={false}\n        onSubmit={(selected) => {\n          console.log(selected);\n        }}\n        emptyScreenImage=""\n        emptyScreenHeader="Nobody here yet"\n        emptyScreenDescription="Invite somebody and they will show up in this list."\n        searchEmptyScreenImage=""\n        searchEmptyScreenHeader="Nothing matches"\n        searchEmptyScreenDescription="Try a shorter query."\n      />\n    </div>\n  );\n}\n```\n\n## Props\n\nEvery `with…` flag below takes `true` or nothing at all — `withSearch={false}` does not\ntype-check. Setting one makes the props listed beside it required, which is how the type says\n"a search box needs somewhere to send the query".\n\n<!-- props:start SelectorProps -->\n\n_Generated by `pnpm readme:props` from `SelectorProps` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop                           | Type                                                                                              | Required | Default      | Description                                                                                                                                                                                                             |\n| ------------------------------ | ------------------------------------------------------------------------------------------------- | -------- | ------------ | ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| `disableSubmitButton`          | `boolean`                                                                                         | **yes**  | –            | Whether the primary button is dead. With `withFooterInput` an empty input disables it too, whatever this says.                                                                                                          |\n| `emptyScreenDescription`       | `string`                                                                                          | **yes**  | –            | Paragraph under that heading.                                                                                                                                                                                           |\n| `emptyScreenHeader`            | `string`                                                                                          | **yes**  | –            | Heading for the empty folder.                                                                                                                                                                                           |\n| `emptyScreenImage`             | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>> \\| string`               | **yes**  | –            | Picture for the empty folder. A string is used as an `<img>` source, an element is rendered as it is.                                                                                                                   |\n| `hasNextPage`                  | `boolean`                                                                                         | **yes**  | –            | Whether another page can be fetched.                                                                                                                                                                                    |\n| `isLoading`                    | `boolean`                                                                                         | **yes**  | –            | Initial load: the body is replaced with a skeleton loader                                                                                                                                                               |\n| `isMultiSelect`                | `boolean`                                                                                         | **yes**  | –            | Whether rows carry checkboxes and more than one can be ticked.                                                                                                                                                          |\n| `isNextPageLoading`            | `boolean`                                                                                         | **yes**  | –            | Whether a page request is in flight, which suppresses another one.                                                                                                                                                      |\n| `items`                        | `TSelectorItem[]`                                                                                 | **yes**  | –            | The page of items loaded so far, in the order they are shown.                                                                                                                                                           |\n| `loadNextPage`                 | `(startIndex: number) => Promise<void>`                                                           | **yes**  | –            | Called with the index to start from when the list nears its end, and once with 0 on mount unless `disableFirstFetch` is set. Append to `items`.                                                                         |\n| `onSubmit`                     | `TOnSubmit`                                                                                       | **yes**  | –            | Called with everything the footer holds. Return a promise and the button shows its spinner until it settles. Enter fires it as well.                                                                                    |\n| `rowLoader`                    | `React.ReactNode`                                                                                 | **yes**  | –            | Skeleton for a row that has not arrived yet, and for the whole body during the initial load. `RowLoader` from this folder fits.                                                                                         |\n| `searchEmptyScreenDescription` | `string`                                                                                          | **yes**  | –            | Paragraph under that heading.                                                                                                                                                                                           |\n| `searchEmptyScreenHeader`      | `string`                                                                                          | **yes**  | –            | Heading for a search that found nothing.                                                                                                                                                                                |\n| `searchEmptyScreenImage`       | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>> \\| string`               | **yes**  | –            | The same picture, for a search that found nothing.                                                                                                                                                                      |\n| `submitButtonLabel`            | `string`                                                                                          | **yes**  | –            | Text of the primary button. In multi-select the count is appended in brackets, so pass "Add", not "Add (3)".                                                                                                            |\n| `totalItems`                   | `number`                                                                                          | **yes**  | –            | How many items exist in total, which is what the scrollbar is sized from.                                                                                                                                               |\n| `accessRights`                 | `TAccessRight[]`                                                                                  | no       | –            | The choices in that drop-down.                                                                                                                                                                                          |\n| `accessRightsMode`             | `SelectorAccessRightsMode`                                                                        | no       | –            | Whether each entry shows its `description`.                                                                                                                                                                             |\n| `activeTabId`                  | `string`                                                                                          | no       | –            | Id of the open tab. Selector keeps one selection per tab id and adds them all up, so switching tabs does not drop what was ticked on the other.                                                                         |\n| `alwaysShowFooter`             | `boolean`                                                                                         | no       | –            | Whether the footer stays put instead of appearing with the first tick.                                                                                                                                                  |\n| `bodyIsLoading`                | `boolean`                                                                                         | no       | –            | Ignored. Selector overwrites it with its own `isLoading` before the trail ever sees it; the type demands the field all the same.                                                                                        |\n| `breadCrumbs`                  | `TBreadCrumb[]`                                                                                   | no       | –            | The trail, outermost first. The last entry is the current folder.                                                                                                                                                       |\n| `breadCrumbsLoader`            | `React.ReactNode`                                                                                 | no       | –            | Shown in place of the trail while it loads; `BreadCrumbsLoader` fits.                                                                                                                                                   |\n| `cancelButtonId`               | `string`                                                                                          | no       | –            | `id` attribute of that button.                                                                                                                                                                                          |\n| `cancelButtonLabel`            | `string`                                                                                          | no       | –            | Text of that button.                                                                                                                                                                                                    |\n| `className`                    | `string`                                                                                          | no       | –            | Applied to the outermost element.                                                                                                                                                                                       |\n| `currentFooterInputValue`      | `string`                                                                                          | no       | –            | Initial text of the field. Selector owns the value from then on and hands the edited one to `onSubmit`; changing this prop later does nothing.                                                                          |\n| `dataTestId`                   | `string`                                                                                          | no       | `"selector"` | `data-testid` of the outermost element.                                                                                                                                                                                 |\n| `descriptionText`              | `string`                                                                                          | no       | –            | A line of bold text above the list. It costs the list 32px of height.                                                                                                                                                   |\n| `disableFirstFetch`            | `boolean`                                                                                         | no       | –            | Whether to skip the `loadNextPage(0)` call Selector makes on mount.                                                                                                                                                     |\n| `displayFileExtension`         | `boolean`                                                                                         | no       | –            | Whether a file\'s extension is drawn after its name, in a dimmer colour.                                                                                                                                                 |\n| `folderFormValidation`         | `RegExp`                                                                                          | no       | –            | Matched against the footer input on every keystroke. A match marks the field as in error and shows the kit\'s "contains special characters" line — so it describes what is _forbidden_, not what is allowed.             |\n| `footerCheckboxLabel`          | `string`                                                                                          | no       | –            | Label beside that checkbox.                                                                                                                                                                                             |\n| `footerInputHeader`            | `string`                                                                                          | no       | –            | Label above that field.                                                                                                                                                                                                 |\n| `forceIsMultiSelect`           | `boolean`                                                                                         | no       | –            | Whether an item\'s own `disableMultiSelect` is overruled.                                                                                                                                                                |\n| `headerProps`                  | `HeaderProps`                                                                                     | no       | –            | The header\'s own props. Required once `withHeader` is set.                                                                                                                                                              |\n| `hideBackButton`               | `boolean`                                                                                         | no       | –            | Whether the empty screen\'s "back" link is hidden.                                                                                                                                                                       |\n| `id`                           | `string`                                                                                          | no       | –            | Applied to the outermost element.                                                                                                                                                                                       |\n| `infoBarData`                  | `TInfoBarData`                                                                                    | no       | –            | What that bar says. Nothing is drawn without it.                                                                                                                                                                        |\n| `infoText`                     | `string`                                                                                          | no       | –            | Text of that note.                                                                                                                                                                                                      |\n| `injectedElement`              | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>>`                         | no       | –            | Rendered between the breadcrumbs and the search box. Selector clones it to attach a ref and subtracts its measured height from the list.                                                                                |\n| `isBreadCrumbsLoading`         | `boolean`                                                                                         | no       | `false`      | Whether to replace the trail with `breadCrumbsLoader`.                                                                                                                                                                  |\n| `isChecked`                    | `boolean`                                                                                         | no       | –            | Initial state of the checkbox. Selector owns it from then on and hands the current value to `onSubmit`; changing this prop later does nothing.                                                                          |\n| `isContentLoading`             | `boolean`                                                                                         | no       | –            | Content refresh: the current body stays on screen dimmed; wins over isLoading                                                                                                                                           |\n| `isSearchLoading`              | `boolean`                                                                                         | no       | –            | Whether to replace the box with `searchLoader`.                                                                                                                                                                         |\n| `isSSR`                        | `boolean`                                                                                         | no       | –            | Whether to render every item as plain markup instead of virtualising. The list needs a measured height, which server rendering cannot give it.                                                                          |\n| `maxSelectedItems`             | `number`                                                                                          | no       | –            | Largest number of items that may be ticked at once. Beyond it the unticked rows go grey and stop responding, with no message of their own.                                                                              |\n| `onAccessRightsChange`         | `(access: TAccessRight) => void`                                                                  | no       | –            | Called when the choice changes.                                                                                                                                                                                         |\n| `onCancel`                     | `() => void`                                                                                      | no       | –            | Called by that button — and by Escape, which Selector listens for on the window whether or not the button is there.                                                                                                     |\n| `onClearSearch`                | `(callback?: VoidFunction) => void`                                                               | no       | –            | Called by the box\'s cross and by the empty screen\'s "clear filter" link. Call the callback to take the selector out of its searching state.                                                                             |\n| `onClose`                      | `VoidFunction`                                                                                    | no       | –            | Called by the backdrop and by the aside. Required once `useAside` is set.                                                                                                                                               |\n| `onSearch`                     | `(value: string, callback?: VoidFunction) => void`                                                | no       | –            | Called with the trimmed query once typing stops. Call the callback to put the selector into its searching state, which is what swaps the empty screen for the search one. An empty query calls `onClearSearch` instead. |\n| `onSelect`                     | `(item: TSelectorItem, isDoubleClick: boolean, doubleClickCallback: () => Promise<void>) => void` | no       | –            | Called when a row is clicked, before Selector updates its own selection. The third argument submits with that one item, which is how a double click confirms a choice.                                                  |\n| `onSelectAll`                  | `() => void`                                                                                      | no       | –            | Called when the row is clicked. Selector ticks and unticks the loaded items itself; this is a notification, not the implementation.                                                                                     |\n| `onSelectBreadCrumb`           | `(item: TBreadCrumb) => void`                                                                     | no       | –            | Called with the crumb that was clicked. Navigating is your job: fetch that folder and hand back new `items` and `breadCrumbs`.                                                                                          |\n| `renderCustomItem`             | `TRenderCustomItem`                                                                               | no       | –            | Replaces the text of a row, keeping its avatar, checkbox and layout.                                                                                                                                                    |\n| `searchLoader`                 | `React.ReactNode`                                                                                 | no       | –            | Shown in place of the box while `isSearchLoading` is set.                                                                                                                                                               |\n| `searchPlaceholder`            | `string`                                                                                          | no       | –            | Placeholder of the box.                                                                                                                                                                                                 |\n| `searchValue`                  | `string`                                                                                          | no       | –            | Text in the box. Searching is yours to do; this is what is displayed.                                                                                                                                                   |\n| `selectAllIcon`                | `string`                                                                                          | no       | –            | URL of the icon beside it.                                                                                                                                                                                              |\n| `selectAllLabel`               | `string`                                                                                          | no       | –            | Text of that row.                                                                                                                                                                                                       |\n| `selectedAccessRight`          | `null \\| TAccessRight`                                                                            | no       | –            | The chosen access. Selector copies it into its own state on mount and whenever this changes, and hands that copy to `onSubmit`.                                                                                         |\n| `selectedItem`                 | `null \\| TSelectorItem`                                                                           | no       | –            | The one ticked item outside multi-select, matched by `id`.                                                                                                                                                              |\n| `selectedItems`                | `TSelectorItem[]`                                                                                 | no       | –            | Items to start out ticked, matched by `id`. Selector copies them into its own state; it is a starting point, not a controlled value.                                                                                    |\n| `style`                        | `React.CSSProperties`                                                                             | no       | –            | Applied to the outermost element.                                                                                                                                                                                       |\n| `submitButtonId`               | `string`                                                                                          | no       | –            | `id` attribute of the primary button.                                                                                                                                                                                   |\n| `tabsData`                     | `TTabItem[]`                                                                                      | no       | –            | The tabs, in order.                                                                                                                                                                                                     |\n| `useAside`                     | `boolean`                                                                                         | no       | –            | Whether Selector wraps itself in a backdrop and an `Aside`. It is the only way the component becomes a panel; on its own it is a plain box that fills its parent.                                                       |\n| `withAccessRights`             | `true`                                                                                            | no       | –            | Whether the footer carries an access drop-down. It only accepts `true`.                                                                                                                                                 |\n| `withBlur`                     | `boolean`                                                                                         | no       | –            | Ignored. Nothing reads this prop.                                                                                                                                                                                       |\n| `withBreadCrumbs`              | `true`                                                                                            | no       | –            | Whether the folder trail is shown above the list. It only accepts `true`.                                                                                                                                               |\n| `withCancelButton`             | `true`                                                                                            | no       | –            | Whether a second, non-primary button sits in the footer. It only accepts `true`.                                                                                                                                        |\n| `withFooterCheckbox`           | `true`                                                                                            | no       | –            | Whether the footer carries a checkbox. It only accepts `true`, and it makes the footer 110px, or 181px alongside `withFooterInput`.                                                                                     |\n| `withFooterInput`              | `true`                                                                                            | no       | –            | Whether the footer carries a text field — the "save as" name. It only accepts `true`, and it makes the footer 145px instead of 73px.                                                                                    |\n| `withHeader`                   | `true`                                                                                            | no       | –            | Whether the panel has a header bar. It only accepts `true` — leave it out for a selector with no header of its own.                                                                                                     |\n| `withInfo`                     | `true`                                                                                            | no       | –            | Whether a tinted note sits between the search box and the list. It only accepts `true`, and the note is hidden during the initial load.                                                                                 |\n| `withInfoBadge`                | `boolean`                                                                                         | no       | –            | Whether an icon is drawn beside the text.                                                                                                                                                                               |\n| `withInfoBar`                  | `boolean`                                                                                         | no       | –            | Whether a dismissable bar is shown above the list.                                                                                                                                                                      |\n| `withoutBackground`            | `boolean`                                                                                         | no       | –            | Whether the backdrop behind the aside is transparent.                                                                                                                                                                   |\n| `withPadding`                  | `boolean`                                                                                         | no       | `true`       | Whether the body keeps its 16px of padding at the top.                                                                                                                                                                  |\n| `withSearch`                   | `true`                                                                                            | no       | –            | Whether the list can be searched. It only accepts `true`. The box hides itself while the list is empty and no search is running, so an empty folder shows the empty screen rather than a search over nothing.           |\n| `withSelectAll`                | `true`                                                                                            | no       | –            | Whether the "select all" row sits above the list. It only accepts `true`, and the row appears only with `isMultiSelect` and only while no search is running.                                                            |\n| `withTabs`                     | `true`                                                                                            | no       | –            | Whether a tab strip is shown above the list. It only accepts `true`.                                                                                                                                                    |\n\n<!-- props:end -->\n\n### `headerProps`\n\nRequired once `withHeader` is set.\n\n<!-- props:start HeaderProps -->\n\n_Generated by `pnpm readme:props` from `HeaderProps` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop                | Type         | Required | Default | Description                                                                                                                            |\n| ------------------- | ------------ | -------- | ------- | -------------------------------------------------------------------------------------------------------------------------------------- |\n| `headerLabel`       | `string`     | **yes**  | –       | Title of the panel.                                                                                                                    |\n| `onCloseClick`      | `() => void` | **yes**  | –       | Called by the closing cross.                                                                                                           |\n| `isCloseable`       | `boolean`    | no       | `true`  | Whether the closing cross is drawn.                                                                                                    |\n| `onBackClick`       | `() => void` | no       | –       | Called by the back arrow.                                                                                                              |\n| `withoutBackButton` | `false`      | no       | –       | Whether to hide the back arrow. The arrow is drawn only when this is literally `false`; leaving the prop out hides it, as does `true`. |\n| `withoutBorder`     | `boolean`    | no       | –       | Whether the line under the header is removed.                                                                                          |\n\n<!-- props:end -->\n\n### `TSelectorItem`\n\nOne entry of `items`. Only `label` is required; which of the rest matter depends on what the\nrow stands for — a person carries `email` and `status`, a room carries `roomType` and `shared`,\nand the two marker fields `isCreateNewItem` and `isInputItem` turn the row into the create link\nand the inline name field.\n\n<!-- props:start TSelectorItem -->\n\n_Generated by `pnpm readme:props` from `TSelectorItem` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop                   | Type                                                                                                 | Required | Default | Description                                                                                                                                                                                                                                                                         |\n| ---------------------- | ---------------------------------------------------------------------------------------------------- | -------- | ------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| `label`                | `string`                                                                                             | **yes**  | –       | Text of the row. The only field every kind of item must carry.                                                                                                                                                                                                                      |\n| `access`               | `number \\| string`                                                                                   | no       | –       | The user\'s current access, where the row shows one.                                                                                                                                                                                                                                 |\n| `avatar`               | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>> \\| string`                  | no       | –       | URL of the avatar picture. An empty string draws the default one. Picture drawn instead of the folder icon.                                                                                                                                                                         |\n| `color`                | `string`                                                                                             | no       | –       | Colour of the generated logo, when there is no picture. Colour of the generated logo beside the field.                                                                                                                                                                              |\n| `cover`                | `ICover`                                                                                             | no       | –       | The room\'s cover art, which replaces the generated logo. Cover art drawn beside the field.                                                                                                                                                                                          |\n| `createDefineRoomType` | `RoomType`                                                                                           | no       | –       | Which room the create link makes, for that empty screen.                                                                                                                                                                                                                            |\n| `defaultInputValue`    | `string`                                                                                             | no       | –       | Text the field starts with.                                                                                                                                                                                                                                                         |\n| `disabledText`         | `string`                                                                                             | no       | –       | Text shown at the end of a disabled row, saying why.                                                                                                                                                                                                                                |\n| `disableMultiSelect`   | `boolean`                                                                                            | no       | –       | Whether this row stays single-select while the rest are not.                                                                                                                                                                                                                        |\n| `displayName`          | `string`                                                                                             | no       | –       | Full name, where it differs from `label`.                                                                                                                                                                                                                                           |\n| `dropDownItems`        | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>>[]`                          | no       | –       | Entries of a menu opened instead of calling `onCreateClick`.                                                                                                                                                                                                                        |\n| `email`                | `string`                                                                                             | no       | –       | Shown under the name, and handed to `renderCustomItem`.                                                                                                                                                                                                                             |\n| `fileExst`             | `string`                                                                                             | no       | –       | Extension including the dot; shown after the name with `displayFileExtension`.                                                                                                                                                                                                      |\n| `filesCount`           | `number`                                                                                             | no       | –       | How many files it holds.                                                                                                                                                                                                                                                            |\n| `fileType`             | `FileType`                                                                                           | no       | –       | Which kind of document it is, which picks the icon.                                                                                                                                                                                                                                 |\n| `foldersCount`         | `number`                                                                                             | no       | –       | How many sub-folders it holds.                                                                                                                                                                                                                                                      |\n| `forceIsMultiSelect`   | `boolean`                                                                                            | no       | –       | Overrules this row\'s own `disableMultiSelect`.                                                                                                                                                                                                                                      |\n| `groups`               | `TUserGroup[]`                                                                                       | no       | –       | Groups the user belongs to.                                                                                                                                                                                                                                                         |\n| `hasAvatar`            | `boolean`                                                                                            | no       | –       | Whether the user has a picture at all, which picks the fallback.                                                                                                                                                                                                                    |\n| `hotkey`               | `string`                                                                                             | no       | –       | Shortcut printed on the right of the row.                                                                                                                                                                                                                                           |\n| `icon`                 | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>> \\| string \\| TSvgComponent` | no       | –       | The icon: a URL, or an SVG component the row renders itself. URL of the room\'s own logo. Icon beside the field: a URL, or an element rendered as it is. A URL for remotely hosted icons, or a rendered element for the ones bundled as SVG components (see utils/ai/getServerIcon). |\n| `iconOriginal`         | `string`                                                                                             | no       | –       | URL of the logo before cropping.                                                                                                                                                                                                                                                    |\n| `id`                   | `number \\| string`                                                                                   | no       | –       | Identifies the item. Selection is matched on it throughout, so two rows sharing an id tick and untick together.                                                                                                                                                                     |\n| `isAdmin`              | `boolean`                                                                                            | no       | –       | Whether the user is a full admin.                                                                                                                                                                                                                                                   |\n| `isCollaborator`       | `boolean`                                                                                            | no       | –       | Whether the user is a power user.                                                                                                                                                                                                                                                   |\n| `isCreateNewItem`      | `boolean`                                                                                            | no       | –       | Marks the row as the "create new" entry. It must be first in `items`, and it is what the empty screen turns into its create link.                                                                                                                                                   |\n| `isDisabled`           | `boolean`                                                                                            | no       | –       | Whether the row is greyed out and ignores clicks.                                                                                                                                                                                                                                   |\n| `isFolder`             | `boolean`                                                                                            | no       | –       | Marks the row as a folder, which lets a click open it. Marks the row as openable, as a folder is.                                                                                                                                                                                   |\n| `isGroup`              | `boolean`                                                                                            | no       | –       | Marks the row as a group, which draws the group avatar.                                                                                                                                                                                                                             |\n| `isInputItem`          | `boolean`                                                                                            | no       | –       | Marks the row as the inline name field. It must be second in `items`, right after the "create new" row, and it takes over the whole body while it is there.                                                                                                                         |\n| `isMCP`                | `boolean`                                                                                            | no       | –       | Marks the row as an MCP server, which draws the server tile.                                                                                                                                                                                                                        |\n| `isOwner`              | `boolean`                                                                                            | no       | –       | Whether the user owns the portal.                                                                                                                                                                                                                                                   |\n| `isRoomAdmin`          | `boolean`                                                                                            | no       | –       | Whether the user administers a room.                                                                                                                                                                                                                                                |\n| `isRoomsOnly`          | `boolean`                                                                                            | no       | –       | Whether only rooms may be created here, which picks the form-room empty screen.                                                                                                                                                                                                     |\n| `isSectionSeparator`   | `boolean`                                                                                            | no       | –       | Makes that divider a section break, 25px tall.                                                                                                                                                                                                                                      |\n| `isSelected`           | `boolean`                                                                                            | no       | –       | Whether the row starts out ticked. Selector recomputes it from `selectedItems` and its own state, so setting it here is a starting point.                                                                                                                                           |\n| `isSeparator`          | `boolean`                                                                                            | no       | –       | Renders the row as a thin divider, 16px tall, that cannot be clicked.                                                                                                                                                                                                               |\n| `isSystem`             | `boolean`                                                                                            | no       | –       | Whether this is a built-in group such as Everyone. System rows are sorted to the top and a divider is inserted under the first of them.                                                                                                                                             |\n| `isTemplate`           | `boolean`                                                                                            | no       | –       | Whether the room is a template, which changes its logo.                                                                                                                                                                                                                             |\n| `isVisitor`            | `boolean`                                                                                            | no       | –       | Whether the user is a guest.                                                                                                                                                                                                                                                        |\n| `key`                  | `string`                                                                                             | no       | –       | React key of the row.                                                                                                                                                                                                                                                               |\n| `lifetimeTooltip`      | `null \\| string`                                                                                     | no       | –       | Tooltip about the file\'s lifetime.                                                                                                                                                                                                                                                  |\n| `name`                 | `string`                                                                                             | no       | –       | Name of the group.                                                                                                                                                                                                                                                                  |\n| `onAcceptInput`        | `(value: string) => void`                                                                            | no       | –       | Called with the typed name when the tick is clicked or Enter pressed.                                                                                                                                                                                                               |\n| `onBackClick`          | `VoidFunction`                                                                                       | no       | –       | Called by the empty screen\'s "back" link.                                                                                                                                                                                                                                           |\n| `onCancelInput`        | `VoidFunction`                                                                                       | no       | –       | Called when the cross is clicked or Escape pressed.                                                                                                                                                                                                                                 |\n| `onCreateClick`        | `VoidFunction`                                                                                       | no       | –       | Called when the row is clicked, unless `dropDownItems` is set.                                                                                                                                                                                                                      |\n| `parentId`             | `number \\| string`                                                                                   | no       | –       | Folder the file sits in. Folder this one sits in. Folder the room sits in.                                                                                                                                                                                                          |\n| `placeholder`          | `string`                                                                                             | no       | –       | Placeholder of the field.                                                                                                                                                                                                                                                           |\n| `private`              | `boolean`                                                                                            | no       | –       | Whether the room is private, which adds the shield badge.                                                                                                                                                                                                                           |\n| `role`                 | `AvatarRole`                                                                                         | no       | –       | Badge drawn on the avatar.                                                                                                                                                                                                                                                          |\n| `roomType`             | `RoomType`                                                                                           | no       | –       | Which room it is, which picks the default logo. Which room logo to draw beside the field.                                                                                                                                                                                           |\n| `rootFolderType`       | `number \\| string`                                                                                   | no       | –       | Root section it belongs to.                                                                                                                                                                                                                                                         |\n| `security`             | `FileEntryDtoIntegerAllOfSecurity`                                                                   | no       | –       | What the current user may do with it.                                                                                                                                                                                                                                               |\n| `shared`               | `boolean`                                                                                            | no       | –       | Whether the room is shared, which adds the badge on its logo.                                                                                                                                                                                                                       |\n| `specialFolderScope`   | `SpecialFolderScope`                                                                                 | no       | –       | Marks the row as a virtual folder such as Recent or Favorites.                                                                                                                                                                                                                      |\n| `status`               | `EmployeeStatus`                                                                                     | no       | –       | Whether the account is active, pending or disabled.                                                                                                                                                                                                                                 |\n| `templateAccess`       | `FileShare`                                                                                          | no       | –       | The current user\'s access to that template.                                                                                                                                                                                                                                         |\n| `templateIsOwner`      | `boolean`                                                                                            | no       | –       | Whether the current user owns that template.                                                                                                                                                                                                                                        |\n| `userType`             | `EmployeeType`                                                                                       | no       | –       | Which type label is drawn — translated through the app\'s i18n instance.                                                                                                                                                                                                             |\n| `viewUrl`              | `string`                                                                                             | no       | –       | Link the row\'s title opens.                                                                                                                                                                                                                                                         |\n\n<!-- props:end -->\n\n### `TBreadCrumb`\n\n<!-- props:start TBreadCrumb -->\n\n_Generated by `pnpm readme:props` from `TBreadCrumb` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop             | Type                 | Required | Default | Description                                                           |\n| ---------------- | -------------------- | -------- | ------- | --------------------------------------------------------------------- |\n| `id`             | `number \\| string`   | **yes**  | –       | Identifies the crumb; it is what `onSelectBreadCrumb` is handed back. |\n| `label`          | `string`             | **yes**  | –       | Text of the crumb.                                                    |\n| `isAgent`        | `boolean`            | no       | –       | Whether the crumb stands for an agent, which draws the agent\'s icon.  |\n| `isRoom`         | `boolean`            | no       | –       | Whether the crumb stands for a room, which draws the room\'s logo.     |\n| `minWidth`       | `string`             | no       | –       | Smallest width this crumb may shrink to, as a CSS length.             |\n| `onClick`        | `TOnBreadCrumbClick` | no       | –       | Called instead of the default navigation when this crumb is clicked.  |\n| `roomType`       | `RoomType`           | no       | –       | Which room icon to draw, when `isRoom` is set.                        |\n| `rootFolderType` | `FolderType`         | no       | –       | Root section the crumb belongs to, which picks its icon.              |\n| `shared`         | `boolean`            | no       | –       | Whether the room is shared, which adds the badge on its logo.         |\n\n<!-- props:end -->\n\n### `TAccessRight`\n\n<!-- props:start TAccessRight -->\n\n_Generated by `pnpm readme:props` from `TAccessRight` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop          | Type               | Required | Default | Description                                                 |\n| ------------- | ------------------ | -------- | ------- | ----------------------------------------------------------- |\n| `access`      | `number \\| string` | **yes**  | –       | The value handed back to you; the component never reads it. |\n| `key`         | `string`           | **yes**  | –       | Identifies the entry within the drop-down.                  |\n| `label`       | `string`           | **yes**  | –       | Text of the entry.                                          |\n| `description` | `string`           | no       | –       | Second line under the label, in the detailed mode.          |\n| `isSeparator` | `boolean`          | no       | –       | Whether this entry is a divider rather than a choice.       |\n\n<!-- props:end -->\n\n### `TInfoBarData`\n\n<!-- props:start TInfoBarData -->\n\n_Generated by `pnpm readme:props` from `TInfoBarData` in `Selector.types.ts`. Do not edit; edit the JSDoc._\n\n| Prop          | Type                                                                                | Required | Default | Description                                                           |\n| ------------- | ----------------------------------------------------------------------------------- | -------- | ------- | --------------------------------------------------------------------- |\n| `description` | `React.ReactNode`                                                                   | **yes**  | –       | Everything under the title.                                           |\n| `title`       | `string`                                                                            | **yes**  | –       | Bold first line of the bar.                                           |\n| `className`   | `string`                                                                            | no       | –       | Applied to the bar.                                                   |\n| `icon`        | `React.ReactElement<unknown, string \\| React.JSXElementConstructor<any>> \\| string` | no       | –       | Icon on the left: a URL for `<img>`, or an element rendered as it is. |\n| `onClose`     | `VoidFunction`                                                                      | no       | –       | Called by the bar\'s own cross. Without it no cross is drawn.          |\n\n<!-- props:end -->\n\n### Enums\n\n<!-- enums:start -->\n\n| Enum                       | Members                                                              |\n| -------------------------- | -------------------------------------------------------------------- |\n| `SelectorAccessRightsMode` | `Compact`, `Detailed`                                                |\n| `AvatarRole`               | `owner`, `admin`, `guest`, `user`, `manager`, `collaborator`, `none` |\n\n<!-- enums:end -->\n\n## Recipes\n\n### Loading\n\n`isLoading` replaces the body with `rowLoader` on the first fetch. `isContentLoading` is the\nother one: it leaves the rows where they are and dims them, which is what a search or a folder\nchange wants — and it wins when both are set.\n\n```tsx\nimport { useCallback, useState } from "react";\nimport {\n  RowLoader,\n  SearchLoader,\n  Selector,\n  type TSelectorItem,\n} from "@onlyoffice/apps-ui-kit/components/selector";\n\nexport function SearchablePeople({\n  fetchPage,\n}: {\n  fetchPage: (query: string) => Promise<TSelectorItem[]>;\n}) {\n  const [items, setItems] = useState<TSelectorItem[]>([]);\n  const [query, setQuery] = useState("");\n  const [isFirstLoad, setIsFirstLoad] = useState(true);\n  const [isRefreshing, setIsRefreshing] = useState(false);\n\n  const run = useCallback(\n    async (next: string, first: boolean) => {\n      if (first) setIsFirstLoad(true);\n      else setIsRefreshing(true);\n\n      setItems(await fetchPage(next));\n      setIsFirstLoad(false);\n      setIsRefreshing(false);\n    },\n    [fetchPage],\n  );\n\n  const loadNextPage = useCallback(async () => {\n    await run(query, true);\n  }, [query, run]);\n\n  return (\n    <div style={{ width: 480, height: 485 }}>\n      <Selector\n        items={items}\n        totalItems={items.length}\n        hasNextPage={false}\n        isNextPageLoading={false}\n        isLoading={isFirstLoad}\n        isContentLoading={isRefreshing}\n        loadNextPage={loadNextPage}\n        rowLoader={<RowLoader isContainer />}\n        withSearch\n        searchLoader={<SearchLoader />}\n        isSearchLoading={false}\n        searchValue={query}\n        searchPlaceholder="Search"\n        onSearch={(value, entered) => {\n          setQuery(value);\n          entered?.();\n          void run(value, false);\n        }}\n        onClearSearch={(left) => {\n          setQuery("");\n          left?.();\n          void run("", false);\n        }}\n        isMultiSelect={false}\n        submitButtonLabel="Add"\n        disableSubmitButton={false}\n        onSubmit={(selected) => {\n          console.log(selected);\n        }}\n        emptyScreenImage=""\n        emptyScreenHeader="Nobody here yet"\n        emptyScreenDescription="Invite somebody and they will show up in this list."\n        searchEmptyScreenImage=""\n        searchEmptyScreenHeader="Nothing matches"\n        searchEmptyScreenDescription="Try a shorter query."\n      />\n    </div>\n  );\n}\n```\n\n### Many at once, with a header and a cancel button\n\n`isMultiSelect` puts a checkbox on every row and appends the count to the submit label, so pass\n"Add", not "Add (3)". The footer appears with the first tick unless `alwaysShowFooter` is set.\n\n```tsx\nimport { useCallback, useState } from "react";\nimport {\n  RowLoader,\n  Selector,\n  type TSelectorItem,\n} from "@onlyoffice/apps-ui-kit/components/selector";\n\nexport function PickSeveral({\n  people,\n  onDone,\n}: {\n  people: TSelectorItem[];\n  onDone: (chosen: TSelectorItem[]) => void;\n}) {\n  const [isSaving, setIsSaving] = useState(false);\n  const loadNextPage = useCallback(async () => {}, []);\n\n  return (\n    <div style={{ width: 480, height: 485 }}>\n      <Selector\n        withHeader\n        headerProps={{\n          headerLabel: "Add people",\n          onCloseClick: () => onDone([]),\n          onBackClick: () => {},\n          withoutBackButton: false,\n          withoutBorder: false,\n        }}\n        items={people}\n        totalItems={people.length}\n        hasNextPage={false}\n        isNextPageLoading={false}\n        isLoading={false}\n        disableFirstFetch\n        loadNextPage={loadNextPage}\n        rowLoader={<RowLoader isContainer isMultiSelect />}\n        isMultiSelect\n        withSelectAll\n        selectAllLabel="All accounts"\n        selectAllIcon=""\n        onSelectAll={() => {}}\n        withCancelButton\n        cancelButtonLabel="Cancel"\n        onCancel={() => onDone([])}\n        submitButtonLabel="Add"\n        disableSubmitButton={isSaving}\n        onSubmit={async (chosen) => {\n          setIsSaving(true);\n          onDone(chosen);\n          setIsSaving(false);\n        }}\n        emptyScreenImage=""\n        emptyScreenHeader="Nobody here yet"\n        emptyScreenDescription="Invite somebody and they will show up in this list."\n        searchEmptyScreenImage=""\n        searchEmptyScreenHeader="Nothing matches"\n        searchEmptyScreenDescription="Try a shorter query."\n      />\n    </div>\n  );\n}\n```\n\n### As a side panel\n\n`useAside` is the only thing that makes Selector a panel: it wraps itself in a\n[`Backdrop`](../backdrop/README.md) and an [`Aside`](../aside/README.md) at z-index 310. There\nis still no visibility prop — mount it when it should be open.\n\n```tsx\nimport { useCallback, useState } from "react";\nimport {\n  RowLoader,\n  Selector,\n  type TSelectorItem,\n} from "@onlyoffice/apps-ui-kit/components/selector";\n\nexport function PeoplePanel({ people }: { people: TSelectorItem[] }) {\n  const [isOpen, setIsOpen] = useState(false);\n  const loadNextPage = useCallback(async () => {}, []);\n\n  return (\n    <>\n      <button type="button" onClick={() => setIsOpen(true)}>\n        Members\n      </button>\n\n      {isOpen ? (\n        <Selector\n          useAside\n          onClose={() => setIsOpen(false)}\n          withHeader\n          headerProps={{\n            headerLabel: "Members",\n            onCloseClick: () => setIsOpen(false),\n          }}\n          items={people}\n          totalItems={people.length}\n          hasNextPage={false}\n          isNextPageLoading={false}\n          isLoading={false}\n          disableFirstFetch\n          loadNextPage={loadNextPage}\n          rowLoader={<RowLoader isContainer />}\n          isMultiSelect={false}\n          submitButtonLabel="Add"\n          disableSubmitButton={false}\n          onSubmit={() => setIsOpen(false)}\n          emptyScreenImage=""\n          emptyScreenHeader="Nobody here yet"\n          emptyScreenDescription="Invite somebody and they will show up in this list."\n          searchEmptyScreenImage=""\n          searchEmptyScreenHeader="Nothing matches"\n          searchEmptyScreenDescription="Try a shorter query."\n        />\n      ) : null}\n    </>\n  );\n}\n```\n\n### "Save as": a folder trail and a file name\n\n`withBreadCrumbs` draws the trail above the list and `withFooterInput` puts a name field in the\nfooter. A crumb click only reports the crumb — loading that folder is yours — and the edited\nname comes back as `onSubmit`\'s third argument.\n\n```tsx\nimport { useCallback, useState } from "react";\nimport {\n  BreadCrumbsLoader,\n  RowLoader,\n  Selector,\n  type TBreadCrumb,\n  type TSelectorItem,\n} from "@onlyoffice/apps-ui-kit/components/selector";\n\nexport function SaveAs({\n  folders,\n  trail,\n  openFolder,\n  save,\n}: {\n  folders: TSelectorItem[];\n  trail: TBreadCrumb[];\n  openFolder: (crumb: TBreadCrumb) => void;\n  save: (folder: TSelectorItem | undefined, name: string) => void;\n}) {\n  const [folder, setFolder] = useState<TSelectorItem | null>(null);\n  const loadNextPage = useCallback(async () => {}, []);\n\n  return (\n    <div style={{ width: 480, height: 485 }}>\n      <Selector\n        withBreadCrumbs\n        breadCrumbs={trail}\n        onSelectBreadCrumb={openFolder}\n        isBreadCrumbsLoading={false}\n        breadCrumbsLoader={<BreadCrumbsLoader />}\n        bodyIsLoading={false}\n        withFooterInput\n        footerInputHeader="File name"\n        currentFooterInputValue="Report.docx"\n        items={folders}\n        totalItems={folders.length}\n        hasNextPage={false}\n        isNextPageLoading={false}\n        isLoading={false}\n        disableFirstFetch\n        loadNextPage={loadNextPage}\n        rowLoader={<RowLoader isContainer />}\n        isMultiSelect={false}\n        selectedItem={folder}\n        onSelect={(item) => setFolder(item)}\n        submitButtonLabel="Save"\n        disableSubmitButton={false}\n        onSubmit={(selected, _access, fileName) => save(selected[0], fileName)}\n        emptyScreenImage=""\n        emptyScreenHeader="This folder is empty"\n        emptyScreenDescription="Save here, or pick another folder."\n        searchEmptyScreenImage=""\n        searchEmptyScreenHeader="Nothing matches"\n        searchEmptyScreenDescription="Try a shorter query."\n      />\n    </div>\n  );\n}\n```\n\n## Behaviour the types don\'t state\n\n- **It needs a parent with a real height.** The body measures itself and hands the pixel count\n  to the virtual list; in a box of automatic height the list is zero tall and you see the\n  chrome with nothing under it. `isSSR` is the escape hatch — it renders every row as plain\n  markup until a height is measured.\n- **The list height is arithmetic, not layout.** Each part is subtracted from the measured\n  body: search 44px, tabs 33px, breadcrumbs 38px, "select all" 61px, `descriptionText` 32px,\n  padding 16px, header 54px (70px without tabs), footer 73px — 110px with the checkbox, 145px\n  with the input, 181px with both, plus 20px while the input is in error. A part you style to\n  a different height will not move the list.\n- **Selection is seeded, not controlled.** `selectedItems`, `selectedItem`, `isChecked` and\n  `currentFooterInputValue` are copied into Selector\'s own state; changing them afterwards does\n  not move the ticks, and the current values come back to you through `onSubmit`, never through\n  a change handler.\n- **It fetches on mount.** `loadNextPage(0)` runs in an effect on the first render unless\n  `disableFirstFetch` is set — including when you have already put a page in `items`.\n- **Escape and Enter are bound to the window**, not to the panel: Escape calls `onCancel` and\n  Enter submits wherever focus happens to be on the page, and both stand down only while the\n  inline name row is open. Two Selectors on one page both answer the same key.\n- **The search callback is what shows the search empty screen.** `onSearch` hands you the\n  trimmed query and a callback; until you call it Selector does not consider itself searching,\n  so a query that matches nothing shows the _folder_ empty screen. A query that trims to\n  nothing routes to `onClearSearch` instead.\n- **The back arrow is drawn only for `withoutBackButton: false`.** Leaving the prop out hides\n  it, exactly as `true` does.\n- **Rows are 48px, always.** A separator row is 16px, or 25px with `isSectionSeparator`.\n  Nothing measures a row\'s content.\n- **Two rows have fixed positions.** The `isCreateNewItem` row must be first in `items`, and\n  the `isInputItem` row second; the inline name field takes over the whole body while it is\n  there, and the empty screen turns the create row into its link.\n- **`maxSelectedItems` fails silently.** Past the limit the unticked rows go grey and stop\n  responding, with no message and no callback.\n- **A row with `isSystem` is sorted to the top** and a divider is spliced in beneath it.\n- **`bodyIsLoading` and `withBlur` are dead.** The first is overwritten with Selector\'s own\n  `isLoading` before the breadcrumbs see it — the type still demands it once `withBreadCrumbs`\n  is set. The second is destructured and never read.\n- The strings Selector prints itself — the user-type labels, "Back", "Clear filter" and the\n  footer\'s "contains special characters" — come from the app\'s i18n instance, not from props.\n\n## CSS variables\n\n| Variable                                       | Default        | Effect                                                                                                                                       |\n| ---------------------------------------------- | -------------- | -------------------------------------------------------------------------------------------------------------------------------------------- |\n| `--selector-border`                            | 1px solid grey | Footer\'s top line and the "select all" rule, as a `border` shorthand                                                                         |\n| `--selector-body-description-text`             | theme grey     | Colour of `descriptionText`                                                                                                                  |\n| `--selector-breadcrumbs-prev-item-color`       | theme grey     | Crumbs behind the current one, and the dots of a collapsed trail                                                                             |\n| `--selector-breadcrumbs-arrow-right-color`     | theme grey     | Arrows between crumbs                                                                                                                        |\n| `--selector-info-background-color`             | theme grey     | Background of the `withInfo` note                                                                                                            |\n| `--selector-info-color`                        | theme grey     | Text of that note                                                                                                                            |\n| `--selector-item-hover-background`             | theme grey     | Row under the pointer                                                                                                                        |\n| `--selector-item-selected-background`          | theme grey     | The ticked row, outside multi-select                                                                                                         |\n| `--selector-item-disabled-text-color`          | theme grey     | Label of a disabled row                                                                                                                      |\n| `--selector-item-input-button-border`          | 1px solid grey | Tick and cross of the inline name row, and the create-row drop-down, as a `border` shorthand                                                 |\n| `--selector-item-input-button-border-hover`    | theme grey     | Border and icon colour of that tick and cross on hover                                                                                       |\n| `--selector-empty-screen-description-color`    | theme grey     | Paragraph on the empty screen                                                                                                                |\n| `--selector-empty-screen-pressed-button-color` | theme grey     | Paragraph on the other empty screen, drawn without `withSearch` when the create row sets `isRoomsOnly` with a form-filling or data room type |\n\nThe two empty-screen variables show only while the list is empty. The theme also defines\n`--selector-empty-screen-button-color` and `--selector-empty-screen-hover-button-color`, but\nthe stylesheet reads neither, so setting them changes nothing.\n\n## Accessibility\n\n- **The list is not reachable from the keyboard.** Rows are `<div>`s with an `onClick`, carry\n  no role and are never focusable; only the rows near the viewport exist in the DOM at all, so\n  assistive technology is given no list, no count and no position. In multi-select the row\'s\n  checkbox is focusable with Tab and toggled with Space, and that is the only way through the\n  list; outside multi-select a row can be picked only with the pointer.\n- **Focus moves into the selector when it mounts**: to the list\'s scroll container, unless the\n  search box already has it, and to the new-name field when that field appears, with its text\n  selected. Neither scrolls the page (`preventScroll`), so a selector further down a page takes\n  focus without pulling the page to itself.\n- The search box is given `tabIndex={1}`, a positive tab index, which pulls it ahead of\n  everything else on the page in tab order.\n- Escape and Enter are listened for on the window, so they act even when focus is outside the\n  panel — and Enter submits without the button being focused.\n- The empty screen\'s create and back controls are `<div>`s with click handlers, not buttons.\n- The footer\'s submit and cancel buttons are native buttons, reached with Tab and pressed with\n  Enter or Space.\n- Give the panel a name yourself: `headerProps.headerLabel` renders as text, not as a label for\n  the region.\n\n## Test ids\n\n| Element               | `data-testid`                                          |\n| --------------------- | ------------------------------------------------------ |\n| The outermost element | `selector`, or `dataTestId`                            |\n| A row                 | `selector-item-<index>`                                |\n| The search box        | `selector_search_input`                                |\n| A breadcrumb          | `selector_bread_crumb_item_<id>`                       |\n| The submit button     | `selector_submit_button`                               |\n| The cancel button     | `selector_cancel_button`                               |\n| The footer input      | `selector_footer_input`                                |\n| The footer checkbox   | `selector_footer_checkbox`                             |\n| The inline name row   | `selector_input_item`                                  |\n| Its tick and cross    | `selector_new_item_accept`, `selector_new_item_cancel` |\n| `RowLoader`           | `row-loader`, with `isContainer`                       |\n| `BreadCrumbsLoader`   | `bread-crumbs-loader`                                  |\n\nOnly the first can be overridden by a prop.\n\n## Related\n\n- [`Aside`](../aside/README.md) — the panel `useAside` wraps this in.\n- [`SearchInput`](../search-input/README.md) — the search box, whose `onChange` gives a string.\n- [`Table`](../table/README.md) — for rows with columns rather than a single label.\n'})))()}n();export{t as default};